!function(){"use strict";function configMoraCtrl($scope,mS,form,toast){$scope.data={},$scope.configMoras=[],$scope.data.tiempoConfiguracion=!0,$scope.totalRecords=0,$scope.limitOptions=[5,10,25,50],$scope.options={boundaryLinks:!1,limitSelect:!0,pageSelect:!0},$scope.query={order:"diasGracia",limit:5,page:1},$scope.get=function(){mS.getData("GET","/ConfigMora/Get").then(response=>{0!=response.id?($scope.configMoras=response.data,$scope.totalRecords=response.data.length>0?response.data[0].totalRecords:0):toast.toastr("warning",response.message,response.titleSms)},error=>console.log(error))},$scope.get(),$scope.abrirModal=function(data,tipo){$scope.tipo=tipo,$scope.tituloModal=1==tipo?"Agregar Config. Mora":"Actualizar Config. Mora",$scope.iconoModal=1==tipo?"fa fa-plus-circle":"fa fa-edit",$scope.colorHeader=1==tipo?"bg-info":"bg-success",$scope.icono=1==tipo?"fa fa-save":"fa fa-edit",$scope.btnModal=1==tipo?"Guardar":"Actualizar",$scope.data=1==tipo?{}:data.configuracionMora,$("#agregar").modal("show")},$("#porcentajeMora").attr("maxlength",3),$scope.$watch("data.porcentajeMora",xMora=>{!form.campo(xMora)&&xMora>100&&($scope.data.porcentajeMora=100)}),$scope.saveUpdate=function(type){if(form.campo($scope.data.diasGracia))toast.toastr("warning","Ingrese los Dias de Gracia",$scope.tituloModal);else if(form.campo($scope.data.porcentajeMora))toast.toastr("warning","Ingrese el Porcenta de Mora",$scope.tituloModal);else{var url=1==type?"/ConfigMora/Post":"/ConfigMora/Put";mS.getData("post",url,$scope.data).then(response=>{if("0"!=response.id)return"1"==response.id?(toast.toastr("success",response.message,response.titleSms),void $("#agregar").modal("hide")):void 0;toast.toastr("warning",response.message,response.titleSms)})}},$scope.eliminarConfigMora=function({configuracionMora:data}){Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar esta Conf. de Mora ahora?</small>",showConfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!1}).then(result=>{result.value&&mS.getData("post","/ConfigMora/Delete?idConfigMora="+data.idConfiguracionMora).then(response=>{if("0"!=response.id)return"1"==response.id?(toast.toastr("warning",response.message,response.titleSms),void $("#agregar").modal("hide")):void 0;toast.toastr("warning",response.message,response.titleSms)})})},$("#agregar").on("hide.bs.modal",e=>{$scope.get(),$scope.data={}})}angular.module("acontPlusApp").controller("configMoraCtrl",configMoraCtrl),configMoraCtrl.$inject=["$scope","mainService","formulario","toastService"]}(window.angular);